:root{color-scheme:dark;--bg:#0c0d16;--surface:#151624;--surface2:#1b1d2e;--border:#303148;--text:#f7f7ff;--muted:#a8a9bc;--purple:#a78bfa;--purple2:#7654e7;--cyan:#65e5ef;--green:#65ddad;--yellow:#ffd480;--red:#ff829a;--radius:19px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse 70% 40% at 70% -13%,#30215d80,transparent),radial-gradient(ellipse 50% 30% at 5% 98%,#12334c64,transparent),var(--bg);min-height:100vh;color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Arial,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}a{color:var(--cyan)}.app{display:grid;grid-template-columns:240px minmax(0,1fr);min-height:100vh;max-width:1800px;margin:auto}.sidebar{padding:27px 16px 22px 20px;border-right:1px solid var(--border);background:#121320a6;position:sticky;top:0;height:100vh;display:flex;flex-direction:column;gap:20px}.logo{display:flex;align-items:center;gap:11px;padding:5px 9px 14px;font-size:23px;font-weight:850;letter-spacing:-1px}.logo-mark{display:grid;place-items:center;width:39px;height:39px;border-radius:13px;background:linear-gradient(140deg,#a68cf7,#5de0f4);color:#111224;font-weight:950;box-shadow:0 7px 25px #8b5cf64a}.logo small{font-size:10px;color:var(--muted);letter-spacing:2px;display:block;font-weight:700;margin-top:-4px}.aside-title{padding:0 12px;color:#74758b;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:2px;margin:6px 0 0}.nav{display:flex;flex-direction:column;gap:4px}.nav-btn{width:100%;display:flex;align-items:center;justify-content:space-between;border:0;border-radius:12px;background:transparent;color:var(--muted);padding:12px 13px;text-align:left;font-weight:650;transition:.18s}.nav-btn:hover{background:#ffffff0a;color:white}.nav-btn.active{color:white;background:linear-gradient(90deg,#6e51d544,#392c6760);box-shadow:inset 3px 0 var(--purple)}.nav-btn span{display:flex;gap:11px;align-items:center}.nav-btn em{font-size:11px;font-style:normal;border-radius:20px;padding:1px 7px;background:#ffffff13;color:var(--muted)}.sidebar-bottom{margin-top:auto;display:grid;gap:9px}.mini-button{width:100%;display:flex;justify-content:center;gap:7px;align-items:center;border:1px solid var(--border);color:var(--muted);background:#1b1b2c;padding:10px;border-radius:11px;font-weight:700}.mini-button:hover{border-color:var(--purple);color:white}.main{padding:30px clamp(18px,4vw,62px) 60px;min-width:0}.topbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:29px}.eyebrow{font-size:11px;color:var(--purple);font-weight:850;letter-spacing:2.2px;text-transform:uppercase}.page-title{margin:2px 0 0;font-weight:870;letter-spacing:-1.45px;font-size:clamp(26px,3vw,36px)}.top-actions{display:flex;gap:9px;align-items:center}.search{min-width:220px;display:flex;align-items:center;gap:9px;background:#1a1b2a;border:1px solid var(--border);border-radius:12px;padding:0 12px}.search input{width:190px;background:none;border:0;outline:0;color:white;height:43px}.search input::placeholder{color:#818299}.primary{background:linear-gradient(125deg,#9877f5,#7257df);border:0;color:white;font-weight:800;border-radius:12px;padding:12px 17px;box-shadow:0 5px 20px #8b5cf64b}.primary:hover{filter:brightness(1.1)}.hero{border:1px solid #6751a170;border-radius:23px;padding:25px 29px;background:radial-gradient(circle at 80% 30%,#674ab36a,transparent 38%),linear-gradient(130deg,#282044,#151827);display:flex;justify-content:space-between;align-items:center;gap:20px;overflow:hidden;position:relative}.hero:after{content:'✦';position:absolute;right:55px;top:-65px;font-size:220px;line-height:1;color:#ffffff08;pointer-events:none}.hero h2{font-size:clamp(20px,2.4vw,29px);margin:6px 0 5px;letter-spacing:-.9px}.hero p{color:#c0bcd5;margin:0;max-width:610px}.hero .primary{white-space:nowrap;z-index:1}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:22px 0 30px}.stat{border:1px solid var(--border);background:#171827cc;border-radius:16px;padding:17px 19px}.stat span{display:block;color:var(--muted);font-size:12px;font-weight:650}.stat strong{display:block;font-size:30px;letter-spacing:-1px;margin-top:5px;line-height:1.2}.stat b{font-size:11px;font-weight:750;color:var(--purple);padding-top:4px;display:block}.section-head{display:flex;align-items:end;justify-content:space-between;gap:10px;margin:30px 0 14px}.section-head h3{margin:0;font-size:20px;letter-spacing:-.6px}.section-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.section-head button{border:0;color:var(--purple);background:transparent;font-weight:750}.continue-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}.continue-card{display:flex;gap:13px;border:1px solid var(--border);background:#171827;border-radius:15px;padding:10px;min-width:0}.continue-cover{flex:0 0 73px;height:98px;border-radius:10px;overflow:hidden;background:linear-gradient(145deg,#352b67,#23415a);display:grid;place-items:center;color:#ffffff8a;font-size:28px}.continue-cover img,.poster img,.detail-poster img{width:100%;height:100%;object-fit:cover}.continue-info{min-width:0;flex:1}.continue-info strong{font-size:13px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.meta{font-size:11px;color:var(--muted)}.progress{height:6px;background:#35364a;border-radius:8px;overflow:hidden;margin:10px 0 7px}.progress span{height:100%;display:block;background:linear-gradient(90deg,var(--purple),var(--cyan));border-radius:8px}.continue-bottom{display:flex;justify-content:space-between;align-items:center;gap:8px}.episode-pill{border:1px solid #6a5c9e;color:#d6c6ff;background:#352951;padding:4px 9px;border-radius:9px;font-size:11px;font-weight:750}.toolrow{display:flex;justify-content:space-between;align-items:center;gap:9px;margin:4px 0 17px;flex-wrap:wrap}.filters{display:flex;gap:7px;flex-wrap:wrap}.filter{background:#171827;border:1px solid var(--border);border-radius:10px;padding:8px 11px;color:var(--muted);font-size:12px;font-weight:750}.filter.active{background:#41336c;color:#fff;border-color:#7462a7}.sort{border:1px solid var(--border);background:#171827;color:var(--text);padding:8px;border-radius:10px;max-width:180px}.anime-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(184px,1fr));gap:17px}.anime-card{min-width:0;overflow:hidden;border:1px solid var(--border);background:#171827;border-radius:16px;transition:.2s;position:relative}.anime-card:hover{transform:translateY(-3px);border-color:#7965b0;box-shadow:0 12px 30px #0005}.poster{height:224px;position:relative;background:radial-gradient(circle at 70% 20%,#7257a6,#272d56 56%,#192537);display:grid;place-items:center;overflow:hidden}.poster:before{content:'✦';font-size:75px;color:#ffffff33}.poster:has(img):before{display:none}.status-badge{position:absolute;top:9px;left:9px;background:#11121ddd;border:1px solid #ffffff35;color:#f7f5ff;padding:4px 8px;border-radius:8px;font-size:10px;font-weight:800;backdrop-filter:blur(12px)}.score-badge{position:absolute;right:9px;bottom:9px;border-radius:8px;padding:4px 8px;background:#161622e8;color:#ffe09a;font-size:11px;font-weight:850}.card-info{padding:12px}.card-title{font-weight:800;font-size:13px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;min-height:39px;line-height:1.35}.card-row{display:flex;justify-content:space-between;gap:8px;margin-top:9px;align-items:center;font-size:11px;color:var(--muted)}.card-row .progress{flex:1;margin:0}.card-actions{display:flex;gap:7px;margin-top:11px}.ghost{border:1px solid var(--border);background:#222337;color:#dcdcec;border-radius:9px;padding:7px 9px;font-weight:750;font-size:11px}.ghost:hover{border-color:var(--purple)}.card-actions .ghost:first-child{flex:1}.plus{background:#47387d;border:1px solid #7961b5;border-radius:9px;color:white;font-weight:900;padding:6px 11px}.plus:hover{background:#624ba4}.empty{border:1px dashed #4b4568;border-radius:18px;background:#191726;padding:36px 22px;text-align:center;color:var(--muted);grid-column:1/-1}.empty .symbol{font-size:37px;margin-bottom:6px}.empty h3{color:white;margin:4px}.empty p{margin:4px 0 17px}.empty button{margin:auto}.footer{margin-top:35px;padding-top:20px;border-top:1px solid var(--border);color:#7d7d95;font-size:11px}.modal-backdrop{position:fixed;inset:0;background:#05050ccf;display:none;align-items:center;justify-content:center;padding:15px;z-index:10;backdrop-filter:blur(8px)}.modal-backdrop.show{display:flex}.modal{width:min(570px,100%);max-height:min(90vh,930px);overflow:auto;border:1px solid #554d76;background:#1a1b2b;border-radius:20px;box-shadow:0 25px 80px #000a}.modal.wide{width:min(690px,100%)}.modal-header{padding:20px 22px 12px;display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.modal-header h2{margin:0;font-size:23px;letter-spacing:-.5px}.x{border:1px solid var(--border);background:#29293d;color:white;width:32px;height:32px;border-radius:9px}.modal-body{padding:9px 22px 22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field{min-width:0}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:5px;color:#d0cfe0;font-size:12px;font-weight:750}.field input,.field select,.field textarea{width:100%;border:1px solid #414157;background:#11121e;color:#fff;border-radius:10px;padding:11px 12px;min-height:42px}.field textarea{min-height:88px;resize:vertical}.field .hint{font-size:10px;color:var(--muted);margin:4px 0 0}.form-actions{display:flex;justify-content:space-between;gap:10px;margin-top:19px}.danger{background:#442331;border:1px solid #a8586d;color:#ffc4cd;border-radius:9px;padding:9px 12px;font-size:12px;font-weight:800}.detail-top{display:flex;gap:18px}.detail-poster{flex:0 0 132px;height:186px;background:linear-gradient(145deg,#674cac,#225970);border-radius:12px;overflow:hidden;display:grid;place-items:center;font-size:39px}.detail-content{flex:1;min-width:0}.detail-content h3{font-size:22px;line-height:1.25;margin:3px 0 9px}.pill{display:inline-block;border:1px solid #56516c;background:#25253b;border-radius:20px;padding:3px 9px;font-size:11px;color:#c7c5d7;margin:0 5px 6px 0}.detail-stats{display:flex;gap:11px;align-items:center;flex-wrap:wrap;margin-top:12px}.detail-stats b{color:var(--cyan)}.notes{white-space:pre-wrap;font-size:13px;color:#c7c7d4;line-height:1.65}.episode-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:7px;margin-top:12px}.episode{aspect-ratio:1;border-radius:9px;border:1px solid #46465a;background:#232438;color:#aaa9bd;font-weight:800;font-size:12px}.episode.watched{border-color:#8e71dd;background:linear-gradient(130deg,#8b6ce7,#5d48ac);color:white}.episode:focus-visible{outline-offset:2px}.episode-pages{display:flex;justify-content:space-between;align-items:center;gap:8px;color:var(--muted);font-size:12px;margin-top:14px}.episode-pages button{background:#25273a;border:1px solid #494a61;color:#e1e0f4;padding:6px 10px;border-radius:8px}.detail-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.details-section{border-top:1px solid var(--border);padding-top:18px;margin-top:20px}.details-section h4{margin:0;font-size:14px}.toast{position:fixed;bottom:23px;right:23px;z-index:25;border:1px solid #7460b7;background:#29213e;color:white;box-shadow:0 12px 34px #0009;padding:12px 16px;border-radius:12px;max-width:340px;opacity:0;transform:translateY(10px);pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:translateY(0)}.hidden{display:none!important}.mobile-backup{display:none}
@media(max-width:1000px){.app{grid-template-columns:75px 1fr}.sidebar{padding:21px 10px}.logo{padding:6px 7px}.logo .name,.aside-title,.nav-btn .nav-label,.nav-btn em,.sidebar-bottom .label{display:none}.nav-btn{justify-content:center;padding:12px}.nav-btn span{gap:0}.sidebar-bottom .mini-button{padding:9px 0}.main{padding:24px}}
@media(max-width:680px){.app{display:block;padding-bottom:72px}.sidebar{height:auto;position:fixed;top:auto;bottom:0;left:0;right:0;z-index:7;display:flex;flex-direction:row;padding:7px;border-top:1px solid var(--border);border-right:0;background:#121321f5;justify-content:center}.logo,.aside-title,.sidebar-bottom{display:none}.nav{flex-direction:row;justify-content:space-around;width:100%}.nav-btn{font-size:20px;padding:8px 13px}.nav-btn span{gap:0}.main{padding:18px 13px 30px}.topbar{display:block}.top-actions{margin-top:13px}.search{flex:1;min-width:0}.search input{width:100%}.top-actions .primary{white-space:nowrap;padding:12px}.mobile-backup{display:flex;gap:8px;margin-top:10px}.mobile-backup .mini-button{width:auto;flex:1}.hero{padding:19px;display:block}.hero .primary{margin-top:15px}.stats{grid-template-columns:repeat(2,1fr);gap:9px;margin:15px 0 24px}.stat{padding:13px}.stat strong{font-size:27px}.anime-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.poster{height:190px}.continue-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:1}.episode-grid{grid-template-columns:repeat(6,minmax(0,1fr))}.detail-poster{flex-basis:90px;height:132px}.detail-content h3{font-size:19px}.modal-body{padding:8px 15px 20px}.modal-header{padding:16px 15px 9px}}

/* Online anime catalog */
.global-discovery{margin:21px 0 27px;border:1px solid #594879;background:linear-gradient(145deg,#1d1a31,#151827);border-radius:21px;padding:22px;box-shadow:0 12px 46px #05040d38}
.discovery-head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
.discovery-head h2{font-size:21px;letter-spacing:-.55px;margin:2px 0 3px}
.discovery-head p{margin:0;color:var(--muted);font-size:12px}
.source-tag{font-size:11px;border:1px solid #665493;color:#cec1ff;border-radius:30px;padding:5px 10px;white-space:nowrap}
.big-search{display:flex;align-items:center;gap:10px;border:1px solid #7460aa;background:#10101d;border-radius:14px;padding:0 10px 0 15px;margin:18px 0 8px;transition:border-color .2s,box-shadow .2s}
.big-search:focus-within{border-color:var(--cyan);box-shadow:0 0 0 3px #65e5ef16}
.big-search input{flex:1;min-width:0;border:0;background:transparent;color:white;height:53px;outline:none;font-size:15px}
.big-search button{background:#342952;border:0;border-radius:8px;color:#cfc4f7;padding:6px 10px}
.search-hint{font-size:11px;color:var(--muted);margin:3px 0 0}
.catalog-state{margin-top:12px;color:#b9b7ca;font-size:12px;min-height:20px}
.catalog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:13px;margin-top:13px}
.catalog-card{border:1px solid #35364d;border-radius:15px;background:#171827;overflow:hidden;display:flex;flex-direction:column;min-width:0;transition:transform .2s,border-color .2s}
.catalog-card:hover{transform:translateY(-2px);border-color:#826ab9}
.catalog-art{height:177px;background:radial-gradient(circle at 75% 10%,#504183,#20354d);position:relative;overflow:hidden}
.catalog-art img{width:100%;height:100%;object-fit:cover;object-position:center 25%}
.catalog-type{position:absolute;top:9px;left:9px;border:1px solid #ffffff35;border-radius:8px;padding:4px 8px;font-weight:800;font-size:10px;background:#0c0d17d9;backdrop-filter:blur(10px)}
.catalog-score{position:absolute;right:9px;top:9px;background:#0c0d17d9;color:#ffe1a2;border-radius:7px;padding:4px 7px;font-size:11px;font-weight:800}
.catalog-info{padding:12px;display:flex;flex-direction:column;flex:1}
.catalog-info h4{font-size:14px;line-height:1.35;margin:0;min-height:37px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.catalog-english{font-size:11px;color:#c4b7f5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:4px;min-height:16px}
.catalog-meta{font-size:11px;color:var(--muted);margin-top:5px}
.catalog-synopsis{font-size:11px;color:#b5b3c5;line-height:1.55;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:51px;margin:10px 0}
.catalog-action{margin-top:auto;display:flex;flex-wrap:wrap;gap:7px}
.catalog-action button{padding:8px 9px;font-size:11px;border-radius:9px;font-weight:800}
.catalog-action .primary{flex:1;box-shadow:none;white-space:nowrap}
.catalog-action .ghost{flex:1;white-space:nowrap}
.catalog-action .in-library{color:#94f3c4;border:1px solid #467d67;background:#163d35}
.catalog-link{display:inline-block;color:#aaeff4;font-size:11px;margin-top:11px;text-decoration:none}
.catalog-link:hover{text-decoration:underline}
.catalog-more{margin:18px auto 0;display:block;min-width:175px}
.catalog-empty{grid-column:1/-1;background:#1a192b;border:1px dashed #4d4669;border-radius:12px;padding:22px;text-align:center;color:var(--muted);font-size:13px}
.catalog-error{border-color:#7a465f;color:#ffb2c0}
.search-chip{font-size:10px;border-radius:99px;color:#b6ebfc;background:#204052;padding:3px 8px;margin-left:5px}
@media(max-width:680px){.global-discovery{margin:16px 0;padding:15px}.catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.catalog-art{height:165px}.catalog-info{padding:10px}.catalog-action{display:grid;grid-template-columns:1fr}.catalog-action button{width:100%}.discovery-head h2{font-size:19px}}
@media(max-width:370px){.catalog-grid{grid-template-columns:1fr}}


/* Season tracking */
.seasons-modal{width:min(980px,100%);max-height:93vh}
.seasons-topline{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:23px 0 11px}
.seasons-topline h4{margin:0;font-size:17px}.season-toolbar{display:flex;gap:8px;flex-wrap:wrap}
.season-scroller{display:flex;gap:10px;overflow-x:auto;padding:3px 1px 11px;scrollbar-color:#7560a4 #1e2033}
.season-tab{position:relative;flex:0 0 163px;min-height:104px;text-align:left;padding:13px;background:#202136;border:1px solid #434058;border-radius:13px;color:#ededfa}
.season-tab.active{border-color:#ac90ff;background:linear-gradient(130deg,#4b347a,#24253d);box-shadow:0 0 0 1px #7b62c0}
.season-tab strong{display:block;font-size:13px}.season-tab small{color:#b3b1cc;font-size:10px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:5px 0}
.season-tab .progress{margin:8px 0 0;height:5px}.season-tab .season-total{color:#bdeedb;font-size:11px;font-weight:800}
.season-banner{display:flex;justify-content:space-between;gap:13px;align-items:center;flex-wrap:wrap;background:#242239;border:1px solid #4b4463;border-radius:13px;padding:14px 15px;margin:5px 0 13px}
.season-banner strong{font-size:16px}.season-banner p{font-size:11px;color:#bebace;margin:4px 0 0}
.season-actions{display:flex;gap:7px;flex-wrap:wrap}.season-actions button{padding:9px 11px}.season-actions button:disabled{opacity:.45;cursor:not-allowed}
.episode-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.ep-row{display:flex;min-width:0;gap:10px;align-items:center;text-align:left;color:#e3e1ef;border:1px solid #3c3c53;border-radius:11px;background:#202135;padding:10px;min-height:62px}
.ep-row:hover{border-color:#997bdb}.ep-row.watched{background:#1a3b34;border-color:#427b6b}.ep-num{width:38px;min-width:38px;height:38px;display:grid;place-items:center;background:#443664;border-radius:9px;font-size:11px;font-weight:850;color:#daccff}.ep-row.watched .ep-num{background:#2b705b;color:white}
.ep-text{display:flex;flex:1;min-width:0;flex-direction:column;gap:2px}.ep-text strong{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ep-text small{font-size:10px;color:#9c9cb7}.ep-check{font-size:17px;font-weight:850;color:#82e5bb}
.season-info{font-size:11px;color:#b7b4ce;margin:8px 0 12px}.season-note{background:#282439;border:1px solid #4f476a;border-radius:10px;padding:10px 12px;color:#c6c0dd;font-size:11px}
@media(max-width:680px){.season-tab{flex-basis:139px;padding:10px}.episode-list{grid-template-columns:1fr}.season-banner{display:block}.season-actions{margin-top:12px}.seasons-modal{max-height:94vh}}

/* AnimeTrack 4.0: episode navigation and robust long-running series */
.episode-jump{display:flex;flex-wrap:wrap;gap:9px;align-items:center;padding:12px 14px;background:#151626;border:1px solid var(--border);border-radius:12px;margin:14px 0}
.episode-jump label{font-size:12px;color:var(--muted);font-weight:700;flex:1 1 210px}.episode-jump input{background:#0f101a;border:1px solid #4c4566;border-radius:9px;padding:9px;color:var(--text);width:140px;min-width:90px;max-width:170px}
.episode-pages{position:sticky;bottom:-22px;z-index:1;background:#1a1b2bf0;backdrop-filter:blur(8px);border-radius:11px;padding:10px 6px}
.season-scroller{scrollbar-width:thin;scrollbar-color:#6656a2 transparent}
@media(max-width:680px){.episode-jump label{flex-basis:100%}.episode-jump input{flex:1}.episode-pages{bottom:-22px}}

/* v5: full-page detail and universal search */
